{
  "interpretation": {
    "name": "TightenLine1WithSharedNutrunner",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Tighten the fasteners of variant F25 at station st1 of line 1 using the shared nutrunner NR7.",
    "constraints": [
      "NR7 must be reserved exclusively for line 1 and released after use",
      "NR7 must be transported to st1 before configure-tool and tighten-fasteners",
      "The tightening program must come from get-program, with no literal torque or tolerance values",
      "The tightening must be evaluated against its program (E5)",
      "transport-tool must be delegated to agvexecutor"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "single execution, now",
    "requested_capabilities": [],
    "omit_services": ["record-tightening"]
  },
  "recipe": {
    "name": "line1-tighten-nr7",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "deliver",
        "steps": [
          {
            "name": "reserve-nr7",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "fetch-program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "deliver",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "return-and-release",
        "steps": [
          {
            "name": "configure-nr7",
            "service": "configure-tool",
            "next": ["tighten-nr7"],
            "dep": ["fetch-program", "reserve-nr7", "transport-to-station"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-nr7",
            "service": "tighten-fasteners",
            "next": ["evaluate-result"],
            "dep": ["configure-nr7", "reserve-nr7", "transport-to-station"],
            "executor": null,
            "params": {}
          },
          {
            "name": "evaluate-result",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-nr7", "fetch-program"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-and-release",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": ["release-nr7"],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-nr7",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
